class Base {
    public:
        virtual void virtualFunction();  // Declares a virtual function; the compiler adds an entry in the vtable for this function
};

class Derived : public Base {
    public:
        void virtualFunction() override;  // Overrides the base virtual function; the compiler updates the vtable entry for Derived
};  // Implementation note: The vptr is added to the class layout, and constructors initialize it to point to the appropriate vtable.

code_example:
#include <iostream>

class Base {
public:
    virtual void show() { std::cout << "Base::show()" << std::endl; }
    virtual ~Base() {}  // Virtual destructor for proper cleanup
};

class Derived : public Base {
public:
    void show() override { std::cout << "Derived::show()" << std::endl; }
};

int main() {
    Base* ptr = new Derived();  // Pointer to Base, but points to Derived object
    ptr->show();  // Calls Derived::show() at runtime via vtable
    delete ptr;  // Calls Derived::~Base() via vtable
    return 0;
}
